import Foundation

@main struct Tests {
    static var passed = 0, failed = 0
    static func test(_ name: String, _ body: () throws -> Void) {
        do { try body(); passed += 1; print("PASS \(name)") } catch { failed += 1; print("FAIL \(name): \(error)") }
    }
    static func expect(_ condition: @autoclosure () throws -> Bool, _ message: String = "Expectation failed") throws { if try !condition() { throw ConfigError.invalid(message) } }
    static func close(_ a: Double, _ b: Double) -> Bool { abs(a-b)<0.0001 }
    static func ready() -> Configuration {
        var c = Configuration.defaults
        c.calibrations["test"] = Calibration(widthMM:100,heightMM:100,confirmed:true)
        c.selectedDevice = "test"; c.safety = Safety(nativeConflictsResolved:true,nativeHorizontalDisabled:false,tapConflictsResolved:true)
        return c
    }
    static func engine(_ config: Configuration? = nil, app: String = "com.google.Chrome") -> GestureEngine { GestureEngine(config:config ?? ready(),app:app,device:"test") }
    static func frame(_ time: Double, _ n: Int = 3, _ x: Double = 0.4, _ y: Double = 0.4, button: Bool = false) -> TouchFrame {
        TouchFrame(time:time,contacts:(0..<n).map { Contact(id:$0,x:x+Double($0)*0.02,y:y) },physicalButton:button)
    }
    static func count(_ triggers: [GestureTrigger]) -> Int { triggers.reduce(0) { $0+$1.count } }
    static func main() throws {
        test("Defaults validate and all twelve gestures exist") { let c = try Configuration.defaults.validated(); try expect(c.mappings.count == 12) }
        test("Exactly three fingers recognize 10 mm / 10 next tabs") { let e=engine(); _=e.process(frame(0)); let t=e.process(frame(0.1,3,0.5)); try expect(count(t)==10); try expect(t.first?.gesture.direction == .right) }
        test("Three finger previous tab") { let e=engine(); _=e.process(frame(0)); try expect(e.process(frame(0.1,3,0.39)).first?.mapping.action.kind == .previousTab) }
        test("Four finger vertical continuous volume 12 mm / three steps") { let e=engine(); _=e.process(frame(0,4)); let t=e.process(frame(0.1,4,0.4,0.52)); try expect(count(t)==3); try expect(t.first?.mapping.action.kind == .volumeUp) }
        test("Four finger volume down") { let e=engine(); _=e.process(frame(0,4)); try expect(e.process(frame(0.1,4,0.4,0.36)).first?.mapping.action.kind == .volumeDown) }
        test("Three finger vertical Mission Control is one-shot") { let e=engine(); _=e.process(frame(0)); try expect(e.process(frame(0.1,3,0.4,0.45)).first?.mapping.action.kind == .missionControl); try expect(e.process(frame(0.2,3,0.4,0.5)).isEmpty) }
        test("Three finger down App Exposé") { let e=engine(); _=e.process(frame(0)); try expect(e.process(frame(0.1,3,0.4,0.35)).first?.mapping.action.kind == .appExpose) }
        test("Two fingers never trigger") { let e=engine(); _=e.process(frame(0,2)); try expect(e.process(frame(0.1,2,0.5)).isEmpty); try expect(e.process(frame(0.2,0)).isEmpty) }
        test("Five fingers invalidate session") { let e=engine(); _=e.process(frame(0)); _=e.process(frame(0.1,5)); try expect(e.process(frame(0.2,3,0.5)).isEmpty) }
        test("Fractional movement retained over frames") { let e=engine(); _=e.process(frame(0)); try expect(count(e.process(frame(0.1,3,0.406)))==0); try expect(count(e.process(frame(0.2,3,0.412)))==1); try expect(count(e.process(frame(0.3,3,0.42)))==1) }
        test("Stationary contacts never repeat") { let e=engine(); _=e.process(frame(0)); _=e.process(frame(0.1,3,0.45)); for i in 2...20 { try expect(e.process(frame(Double(i)*0.05+0.1,3,0.45)).isEmpty) } }
        test("Reversal switches without lifting") { let e=engine(); _=e.process(frame(0)); _=e.process(frame(0.1,3,0.43)); let t=e.process(frame(0.2,3,0.41)); try expect(count(t)==2); try expect(t.first?.gesture.direction == .left) }
        test("Vertical volume reverses without lifting") { let e=engine(); _=e.process(frame(0,4)); _=e.process(frame(0.1,4,0.4,0.48)); let t=e.process(frame(0.2,4,0.4,0.44)); try expect(count(t)==1 && t.first?.mapping.action.kind == .volumeDown) }
        test("No queued fractional action on lift") { let e=engine(); _=e.process(frame(0)); _=e.process(frame(0.1,3,0.416)); try expect(e.process(frame(0.2,0)).isEmpty) }
        test("Tap recognized after lift only") { let e=engine(); try expect(e.process(frame(0)).isEmpty); let t=e.process(frame(0.15,0)); try expect(t.first?.mapping.action.kind == .playPause) }
        test("Four finger tap mute with staggered release") { let e=engine(); _=e.process(frame(0,4)); _=e.process(frame(0.1,3)); try expect(e.process(frame(0.13,0)).first?.mapping.action.kind == .mute) }
        test("Long hold is not tap") { let e=engine(); _=e.process(frame(0)); _=e.process(frame(0.2)); try expect(e.process(frame(0.3,0)).isEmpty) }
        test("Swipe never becomes a tap") { let e=engine(); _=e.process(frame(0)); _=e.process(frame(0.1,3,0.42)); try expect(e.process(frame(0.15,0)).isEmpty) }
        test("Sub-threshold swipe cannot become a tap after activation") { let e=engine(); _=e.process(frame(0)); _=e.process(frame(0.1,3,0.406)); try expect(e.process(frame(0.15,0)).isEmpty) }
        test("Physical mouse down cancels tap") { let e=engine(); _=e.process(frame(0)); e.physicalClick(); try expect(e.process(frame(0.1,0)).isEmpty) }
        test("Button held on contact cancels gesture") { let e=engine(); _=e.process(frame(0,3,0.4,0.4,button:true)); try expect(e.process(frame(0.1,3,0.45)).isEmpty) }
        test("Click mappings always unsupported even imported enabled") { var c=ready(); let g=Gesture(fingers:3,direction:.click); var m=c.mapping(g,app:""); m.enabled=true; c.mappings[g.id]=m; try expect(c.blockedReason(g,mapping:m,device:"test")?.contains("unsupported") == true) }
        test("Finger count change cancels movement") { let e=engine(); _=e.process(frame(0)); _=e.process(frame(0.1,4)); try expect(e.process(frame(0.2,4,0.5)).isEmpty) }
        test("Initial staggered landing settles into four fingers") { let e=engine(); _=e.process(frame(0)); _=e.process(frame(0.02,4)); try expect(count(e.process(frame(0.1,4,0.4,0.44)))==1) }
        test("Identity replacement cancels") { let e=engine(); _=e.process(frame(0)); var f=frame(0.1,3,0.45); f.contacts[0].id=50; try expect(e.process(f).isEmpty); try expect(e.process(frame(0.2,0)).isEmpty) }
        test("Explicit cancellation requires lift to rearm") { let e=engine(); _=e.process(frame(0)); e.cancel(); try expect(e.process(frame(0.1,3,0.45)).isEmpty); _=e.process(frame(0.2,0)); _=e.process(frame(0.3)); try expect(count(e.process(frame(0.4,3,0.42)))==2) }
        test("Duplicate timestamp prevented") { let e=engine(); _=e.process(frame(0)); let f=frame(0.1,3,0.45); try expect(count(e.process(f))==5); try expect(e.process(f).isEmpty) }
        test("Out of order frame ignored") { let e=engine(); _=e.process(frame(1)); try expect(e.process(frame(0.9,3,0.45)).isEmpty) }
        test("NaN contact cancels") { let e=engine(); _=e.process(frame(0)); var f=frame(0.1); f.contacts[0].x = .nan; try expect(e.process(f).isEmpty); try expect(e.process(frame(0.2,0)).isEmpty) }
        test("Duplicate finger IDs rejected") { let e=engine(); var f=frame(0); f.contacts[1].id=0; try expect(e.process(f).isEmpty); try expect(e.process(frame(0.1,0)).isEmpty) }
        test("Missing stream cancels stale session") { let e=engine(); _=e.process(frame(0)); try expect(e.process(frame(1,3,0.45)).isEmpty) }
        test("Implausible jump cancels") { let e=engine(); _=e.process(frame(0)); try expect(e.process(frame(0.1,3,0.8)).isEmpty) }
        test("Diagonal rejected without tap") { let e=engine(); _=e.process(frame(0)); try expect(e.process(frame(0.1,3,0.45,0.45)).isEmpty); try expect(e.process(frame(0.15,0)).isEmpty) }
        test("Direction lock prevents orthogonal actions") { let e=engine(); _=e.process(frame(0)); _=e.process(frame(0.1,3,0.42)); try expect(e.process(frame(0.2,3,0.42,0.5)).isEmpty) }
        test("Tiny movement accumulated through jitter deadband") { let e=engine(); _=e.process(frame(0)); for i in 1...10 { _=e.process(frame(Double(i)*0.01,3,0.4+Double(i)*0.0002)) }; try expect(count(e.process(frame(0.2,3,0.41)))==1) }
        test("App override wins over global") { var c=ready(); c.mappings["3_right"] = Mapping(action:Action(kind:.mute)); try expect(c.mapping(Gesture(fingers:3,direction:.right),app:"com.google.Chrome").action.kind == .nextTab) }
        test("Disabled app profile falls back to global") { var c=ready(); c.profiles[0].enabled=false; c.mappings["3_right"] = Mapping(action:Action(kind:.mute)); try expect(c.mapping(Gesture(fingers:3,direction:.right),app:"com.google.Chrome").action.kind == .mute) }
        test("Disabled app cell stops global inheritance") { var c=ready(); c.profiles[0].mappings["3_right"] = Mapping(enabled:false); let e=engine(c); _=e.process(frame(0)); try expect(e.process(frame(0.1,3,0.45)).isEmpty) }
        test("Other apps initially have no horizontal behavior") { let e=engine(app:"org.example"); _=e.process(frame(0)); try expect(e.process(frame(0.1,3,0.45)).isEmpty) }
        test("Global mapping applies to unprofiled app") { var c=ready(); c.mappings["3_right"] = Mapping(action:Action(kind:.browserForward),continuous:true); let e=engine(c,app:"org.example"); _=e.process(frame(0)); try expect(count(e.process(frame(0.1,3,0.42)))==2) }
        test("App sensitivity override") { var c=ready(); var s=c.sensitivity; s.horizontalMM=2; c.profiles[0].sensitivity=s; let e=engine(c); _=e.process(frame(0)); try expect(count(e.process(frame(0.1,3,0.46)))==3) }
        test("Mapping distance override 0.5 mm") { var c=ready(); c.profiles[0].mappings["3_right"]?.distanceMM=0.5; let e=engine(c); _=e.process(frame(0)); try expect(count(e.process(frame(0.1,3,0.41)))==2) }
        test("Native four finger horizontal emits zero actions") { let e=engine(); _=e.process(frame(0,4)); try expect(e.process(frame(0.1,4,0.5)).isEmpty) }
        test("Reassigned desktop gesture blocked until native disabled") { var c=ready(); c.mappings["4_right"] = Mapping(action:Action(kind:.nextDesktop)); let e=engine(c); _=e.process(frame(0,4)); try expect(e.process(frame(0.1,4,0.5)).isEmpty); c.safety.nativeHorizontalDisabled=true; let e2=engine(c); _=e2.process(frame(0,4)); try expect(count(e2.process(frame(0.1,4,0.5)))==1) }
        test("Uncalibrated trackpad cannot emit actions") { var c=ready(); c.calibrations=[:]; let e=engine(c); _=e.process(frame(0)); try expect(e.process(frame(0.1,3,0.5)).isEmpty); try expect(e.process(frame(0.15,0)).isEmpty) }
        test("Native setup consent required") { var c=ready(); c.safety.nativeConflictsResolved=false; let e=engine(c); _=e.process(frame(0)); try expect(e.process(frame(0.1,3,0.5)).isEmpty) }
        test("Tap consent required") { var c=ready(); c.safety.tapConflictsResolved=false; let e=engine(c); _=e.process(frame(0)); try expect(e.process(frame(0.1,0)).isEmpty) }
        test("Global disabled") { var c=ready(); c.enabled=false; let e=engine(c); _=e.process(frame(0)); try expect(e.process(frame(0.1,3,0.5)).isEmpty) }
        test("Physical axes use separate scales") { var c=ready(); c.calibrations["test"]?.heightMM=50; let e=engine(c); _=e.process(frame(0,4)); try expect(count(e.process(frame(0.1,4,0.4,0.48)))==1) }
        test("Chrome verified command option arrow shortcuts") { let p=ActionPlanner.commands(Action(kind:.previousTab),app:"com.google.Chrome",sensitivity:Sensitivity()); try expect(p == [.shortcut(Shortcut(keyCode:123,modifiers:["command","option"]))]) }
        test("Finder Control Tab avoids window switching") { let p=ActionPlanner.commands(Action(kind:.nextTab),app:"com.apple.finder",sensitivity:Sensitivity()); try expect(p == [.shortcut(Shortcut(keyCode:48,modifiers:["control"]))]) }
        test("System media keys use NX type rather than F8") { try expect(ActionPlanner.commands(Action(kind:.playPause),app:"",sensitivity:Sensitivity()) == [.media(16)]); try expect(ActionPlanner.mediaData(key:16,down:true)==0x100A00); try expect(ActionPlanner.mediaData(key:16,down:false)==0x100B00) }
        test("Next and previous track system commands") { try expect(ActionPlanner.commands(Action(kind:.nextTrack),app:"",sensitivity:Sensitivity()) == [.media(17)]); try expect(ActionPlanner.commands(Action(kind:.previousTrack),app:"",sensitivity:Sensitivity()) == [.media(18)]) }
        test("Volume default exactly two percent") { try expect(ActionPlanner.commands(Action(kind:.volumeUp),app:"",sensitivity:Sensitivity()) == [.volume(0.02)]) }
        test("Volume clamps at both bounds") { try expect(ActionPlanner.volume(0.99,delta:0.02)==1); try expect(ActionPlanner.volume(0.01,delta:-0.02)==0) }
        test("Volume override") { try expect(ActionPlanner.commands(Action(kind:.volumeDown,volumePercent:5),app:"",sensitivity:Sensitivity()) == [.volume(-0.05)]) }
        test("Native and unsupported Notification Center synthesize nothing") { try expect(ActionPlanner.commands(Action(kind:.native),app:"",sensitivity:Sensitivity()).isEmpty); try expect(ActionPlanner.commands(Action(kind:.notificationCenter),app:"",sensitivity:Sensitivity()).isEmpty) }
        test("App-specific shortcut only runs in target app") { let a=Action(kind:.applicationShortcut,bundleID:"target"); try expect(ActionPlanner.commands(a,app:"other",sensitivity:Sensitivity()).isEmpty); try expect(!ActionPlanner.commands(a,app:"target",sensitivity:Sensitivity()).isEmpty) }
        test("Sequences preserve order and are one-shot") { let keys=[Shortcut(keyCode:0),Shortcut(keyCode:1)]; try expect(ActionPlanner.commands(Action(kind:.sequence,shortcuts:keys),app:"",sensitivity:Sensitivity()) == keys.map { .shortcut($0) }); try expect(!ActionKind.sequence.repeatable) }
        test("Atomic configuration persistence roundtrip") { let dir=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString); defer { try? FileManager.default.removeItem(at:dir) }; let store=ConfigurationStore(url:dir.appendingPathComponent("threefinger.json")); var c=ready(); try store.save(c); try expect(try store.load()==c); c.sensitivity.horizontalMM=3.5; try store.save(c); try expect(try store.load()==c) }
        test("Invalid distance rejected without overwriting config") { let dir=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString); defer { try? FileManager.default.removeItem(at:dir) }; let store=ConfigurationStore(url:dir.appendingPathComponent("config.json")); let c=ready(); try store.save(c); var invalid=c; invalid.sensitivity.horizontalMM=0; do { try store.save(invalid); throw ConfigError.invalid("accepted invalid config") } catch { try expect(try store.load()==c) } }
        test("Malformed config preserved") { let url=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString); defer { try? FileManager.default.removeItem(at:url) }; try Data("bad json".utf8).write(to:url); var rejected=false; do { _=try ConfigurationStore(url:url).load() } catch { rejected=true }; try expect(rejected); try expect(try String(contentsOf:url)=="bad json") }
        test("Legacy migration backs up and preserves shortcuts") { let dir=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString); try FileManager.default.createDirectory(at:dir,withIntermediateDirectories:true); defer { try? FileManager.default.removeItem(at:dir) }; let url=dir.appendingPathComponent("threefinger.json"); let legacy=Data(#"{"threshold":0.08,"manipulators":[{"from":{"gesture":"three_finger_swipe_left"},"to":[{"key_code":"open_bracket","modifiers":["left_command","left_shift"]}]}]}"#.utf8); try legacy.write(to:url); let c=try ConfigurationStore(url:url).load(); try expect(c.mappings["3_left"]?.action.kind == .sequence); try expect(c.mapping(Gesture(fingers:3,direction:.left),app:"com.google.Chrome").action.kind == .sequence); let files=try FileManager.default.contentsOfDirectory(at:dir,includingPropertiesForKeys:nil); let backup=files.first { $0.lastPathComponent.hasPrefix("threefinger.legacy-") }; try expect(backup != nil); try expect(try Data(contentsOf:backup!)==legacy) }
        test("Import backs up current config") { let dir=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString); defer { try? FileManager.default.removeItem(at:dir) }; let store=ConfigurationStore(url:dir.appendingPathComponent("config.json")); try store.save(ready()); let exported=dir.appendingPathComponent("export.json"); let encoder=JSONEncoder(); try encoder.encode(Configuration.defaults).write(to:exported); _=try store.importFile(exported); try expect(try FileManager.default.contentsOfDirectory(atPath:dir.path).contains { $0.hasPrefix("threefinger.pre-import-") }) }
        test("Configuration version mismatch rejected") { var c=ready(); c.schemaVersion=99; var rejected=false; do { _=try c.validated() } catch { rejected=true }; try expect(rejected) }
        test("Extreme calibration rejected") { var c=ready(); c.calibrations["test"]?.widthMM=1000; var rejected=false; do { _=try c.validated() } catch { rejected=true }; try expect(rejected) }
        test("Cooldown discards movement rather than replaying") { var c=ready(); c.profiles[0].mappings["3_right"]?.cooldown=0.5; let e=engine(c); _=e.process(frame(0)); _=e.process(frame(0.1,3,0.42)); try expect(e.process(frame(0.2,3,0.44)).isEmpty); try expect(e.process(frame(0.3,3,0.44)).isEmpty) }
        test("Disabled reversed mapping cannot enable the opposite action") { var c=ready(); c.profiles[0].mappings["3_right"]?.reverse=true; c.profiles[0].mappings["3_right"]?.enabled=false; let e=engine(c); _=e.process(frame(0)); try expect(e.process(frame(0.1,3,0.45)).isEmpty) }
        test("Reversed mapping keeps the source interval") { var c=ready(); c.profiles[0].mappings["3_right"]?.reverse=true; c.profiles[0].mappings["3_right"]?.distanceMM=2; let e=engine(c); _=e.process(frame(0)); let t=e.process(frame(0.1,3,0.46)); try expect(count(t)==3 && t.first?.mapping.action.kind == .previousTab) }
        test("Opposing finger movement cannot look like a stationary tap") { let e=engine(); _=e.process(frame(0)); var f=frame(0.1); f.contacts[0].x += 0.03; f.contacts[1].x -= 0.03; _=e.process(f); try expect(e.process(frame(0.15,0)).isEmpty) }
        test("Import cannot carry local consent or calibration to another machine") { let dir=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString); try FileManager.default.createDirectory(at:dir,withIntermediateDirectories:true); defer { try? FileManager.default.removeItem(at:dir) }; let source=dir.appendingPathComponent("profile.json"); try JSONEncoder().encode(ready()).write(to:source); let store=ConfigurationStore(url:dir.appendingPathComponent("config.json")); let c=try store.importFile(source); try expect(c.calibrations.isEmpty && !c.safety.nativeConflictsResolved && !c.safety.tapConflictsResolved && c.selectedDevice.isEmpty); try expect(try store.load()==c) }
        test("No unsafe rate backlog after a cancelled burst") { var c=ready(); c.profiles[0].mappings["3_right"]?.distanceMM=0.5; c.calibrations["test"]?.widthMM=300; let e=engine(c); _=e.process(frame(0)); try expect(e.process(frame(0.1,3,0.59)).isEmpty); try expect(e.process(frame(0.2,3,0.59)).isEmpty) }
        test("Empty custom shortcut rejected") { var c=ready(); c.mappings["3_right"] = Mapping(action:Action(kind:.shortcut,shortcuts:[])); var rejected=false; do { _=try c.validated() } catch { rejected=true }; try expect(rejected) }
        test("Repeated submillimeter samples match physical distance") { let e=engine(); _=e.process(frame(0)); var total=0; for i in 1...200 { total += count(e.process(frame(Double(i)*0.01,3,0.4+Double(i)*0.0005))) }; try expect(total==10) }
        test("X calibration uses one stroke then lift") { var t=CalibrationTrial(horizontal:true); t.observe([Contact(id:1,x:0.2,y:0.2)]); t.observe([Contact(id:1,x:0.5,y:0.2)]); t.observe([]); try expect(close(try t.fullAxisMM(measuredDistance:30),100)) }
        test("Y calibration independently derives physical scale") { var t=CalibrationTrial(horizontal:false); t.observe([Contact(id:1,x:0.2,y:0.2)]); t.observe([Contact(id:1,x:0.2,y:0.6)]); t.observe([]); try expect(close(try t.fullAxisMM(measuredDistance:30),75)) }
        test("Calibration requires lift before applying") { var t=CalibrationTrial(horizontal:true); t.observe([Contact(id:1,x:0.2,y:0.2)]); t.observe([Contact(id:1,x:0.5,y:0.2)]); var rejected=false; do { _=try t.fullAxisMM(measuredDistance:30) } catch { rejected=true }; try expect(rejected) }
        test("Calibration rejects extra fingers and replaced identity") { var t=CalibrationTrial(horizontal:true); t.observe([Contact(id:1,x:0.2,y:0.2)]); t.observe([Contact(id:2,x:0.5,y:0.2)]); try expect(t.invalid); var two=CalibrationTrial(horizontal:true); two.observe(frame(0,2).contacts); try expect(two.invalid) }
        test("Calibration rejects diagonal travel") { var t=CalibrationTrial(horizontal:true); t.observe([Contact(id:1,x:0.2,y:0.2)]); t.observe([Contact(id:1,x:0.5,y:0.5)]); t.observe([]); var rejected=false; do { _=try t.fullAxisMM(measuredDistance:30) } catch { rejected=true }; try expect(rejected) }
        test("Later strokes cannot contaminate completed calibration") { var t=CalibrationTrial(horizontal:true); t.observe([Contact(id:1,x:0.2,y:0.2)]); t.observe([Contact(id:1,x:0.5,y:0.2)]); t.observe([]); t.observe([Contact(id:5,x:0.9,y:0.9)]); try expect(close(try t.fullAxisMM(measuredDistance:30),100)) }
        print("\n\(passed) passed; \(failed) failed")
        if failed>0 { exit(1) }
    }
}
